create or replace function validate_opening_transition_account()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin if not exists(select 1 from chart_accounts a join account_group g on g.group_id=a.account_group_id join account_subsidiaries x on x.account_id=a.account_id where a.account_id=new.transition_account_id and a.account_number='319999'and g.group_code='319'and a.accepts_entries and not a.is_inactive and x.subsidiary_id=new.subsidiary_id and x.is_active)then raise exception'Seleccione la cuenta 319999 - Saldos Iniciales Transitorios asignada a la subsidiaria.';end if;return new;end$$;
drop trigger if exists opening_transition_account_check on opening_balance_runs;create trigger opening_transition_account_check before insert or update of transition_account_id,subsidiary_id on opening_balance_runs for each row execute function validate_opening_transition_account();
revoke all on function validate_opening_transition_account()from public,anon;notify pgrst,'reload schema';
